"""Refresh the file:// manifest copy; never edits clips.json or audio."""
import json
from pathlib import Path

root = Path(__file__).resolve().parent
data = json.loads((root / 'clips.json').read_text())
(root / 'clips-data.js').write_text(
    '// Generated by sync-data.py from clips.json. Do not edit.\n'
    + 'window.PHONEME_CLIPS = ' + json.dumps(data, ensure_ascii=False, indent=2) + ';\n'
)
print('Updated clips-data.js for direct file opening.')
